const input = $input.first().json;
const body = (input && typeof input.body === 'object' && input.body !== null) ? input.body : input;

const seedKeyword = String(body.seed_keyword || body.keyword || '').trim();
if (!seedKeyword) throw new Error('seed_keyword is required');

const location = String(body.location || '').trim();
const language = String(body.language || 'en').trim();
const isGlobal = !location || location.toLowerCase() === 'global';
const limit = Math.max(50, Math.min(3000, Number(body.limit) || 500));

return [{
  json: {
    seed_keyword: seedKeyword,
    location: isGlobal ? '' : location,
    language,
    is_global: isGlobal,
    limit,
    requested_at: body.requested_at || new Date().toISOString()
  }
}];

const input = $input.first().json;
const body = [{
  keyword: input.seed_keyword,
  location_name: input.location || undefined,
  language_code: input.language,
  limit: input.limit || 500,
  include_seed_keyword: true,
  order_by: ['keyword_info.search_volume,desc']
}];
return [{ json: { ...input, dfs_body: body } }];

const input = $input.first().json;
const body = [{
  keyword: input.seed_keyword,
  location_name: input.location || undefined,
  language_code: input.language,
  limit: Math.min(input.limit || 500, 1000),
  include_seed_keyword: false
}];
return [{ json: { ...input, dfs_body: body } }];

const input = $input.first().json;
const limit = input.limit || 500;
const depth = limit <= 100 ? 1 : limit <= 300 ? 2 : limit <= 1500 ? 3 : 4;
const body = [{
  keyword: input.seed_keyword,
  location_name: input.location || undefined,
  language_code: input.language,
  depth
}];
return [{ json: { ...input, dfs_body: body } }];

const allBranchData = $input.all();
const firstItem = $input.first().json;

function extractKwItems(resp) {
  const tasks = resp && resp.tasks;
  if (!Array.isArray(tasks) || !tasks.length) return [];
  const result = tasks[0] && tasks[0].result;
  if (!Array.isArray(result) || !result.length) return [];
  const items = result[0] && result[0].items;
  return Array.isArray(items) ? items : [];
}

function parseKeyword(item) {
  const kw = String(item.keyword || '').trim().toLowerCase();
  if (!kw || kw.length < 2 || kw.length > 100) return null;
  const vi = item.keyword_info || {};
  const vp = item.keyword_properties || {};
  return {
    keyword: kw,
    search_volume: typeof vi.search_volume === 'number' ? vi.search_volume : null,
    cpc: typeof vi.cpc === 'number' ? vi.cpc : null,
    kd: typeof vp.keyword_difficulty === 'number' ? vp.keyword_difficulty : null
  };
}

const allItems = [];
for (const item of allBranchData) {
  allItems.push(...extractKwItems(item.json));
}

const seen = new Set();
const unique = [];
for (const item of allItems) {
  const parsed = parseKeyword(item);
  if (!parsed) continue;
  if (seen.has(parsed.keyword)) continue;
  seen.add(parsed.keyword);
  unique.push(parsed);
}

unique.sort((a, b) => (b.search_volume || 0) - (a.search_volume || 0));

return [{ json: {
  seed_keyword: firstItem.seed_keyword,
  location: firstItem.location,
  language: firstItem.language,
  is_global: firstItem.is_global,
  keywords: unique,
  requested_at: firstItem.requested_at
}}];

const input = $input.first().json;
const keywords = (input.keywords || []).map(k => k.keyword);
return [{ json: { ...input, intent_body: [{ keywords, language_code: input.language }] } }];

const prev = $('Merge & Dedupe').first().json;
const intentResp = $input.first().json;

const intentMap = new Map();
const intentItems = intentResp && intentResp.tasks && intentResp.tasks[0] && intentResp.tasks[0].result;
if (Array.isArray(intentItems)) {
  for (const item of intentItems) {
    if (item && item.keyword) {
      const kw = String(item.keyword).toLowerCase();
      const intent = item.keyword_intent || {};
      intentMap.set(kw, {
        intent: intent.label || 'informational',
        intent_confidence: typeof intent.probability === 'number' ? Math.round(intent.probability * 100) : null
      });
    }
  }
}

function isQuestion(kw) {
  const k = kw.toLowerCase();
  if (/^(how|what|why|when|where|who|which|can |do |does |is |are |should |will |would |could |did )/i.test(k)) return true;
  if (/\?$/.test(k)) return true;
  return false;
}

function classifyIntentRegex(kw) {
  const k = kw.toLowerCase();
  if (isQuestion(kw)) return 'question';
  if (/\b(guide|tutorial|explained|examples?|tips|ideas|ways to|learn|understand|definition|meaning|overview|beginner|introduction|steps?|process|method|technique|strategy)\b/i.test(k)) return 'informational';
  if (/\b(buy|purchase|order|shop|shop now|subscribe|sign up|register|get started|download|hire|book|reserve)\b/i.test(k)) return 'transactional';
  if (/\b(price|pricing|cost|cheap|cheapest|discount|coupon|deal|deals|sale|offer|offers|near me|nearby)\b/i.test(k)) return 'transactional';
  if (/\b(best|top|review|comparison|compare|versus|vs\.?|alternative|alternatives|roundup|pros and cons|benefits|features|rating|ranked)\b/i.test(k)) return 'commercial';
  if (/\b(login|sign in|log in|dashboard|account|portal|homepage|official|website|app)\b/i.test(k)) return 'navigational';
  return 'informational';
}

const keywords = (prev.keywords || []).map(kw => {
  const intentData = intentMap.get(kw.keyword);
  let intent, intent_confidence;
  if (intentData) {
    intent = intentData.intent;
    intent_confidence = intentData.intent_confidence;
    if (intent === 'informational' && isQuestion(kw.keyword)) intent = 'question';
  } else {
    intent = classifyIntentRegex(kw.keyword);
    intent_confidence = null;
  }
  return { ...kw, intent, intent_confidence };
});

return [{ json: { ...prev, keywords } }];

const input = $input.first().json;
const kws = (input.keywords || []).map(k => k.keyword);
return [{ json: {
  ...input,
  kd_body: [{
    keywords: kws,
    location_name: input.location,
    language_code: input.language
  }]
}}];

const prev = $('Attach Intent').first().json;
const kdResp = $input.first().json;

const kdMap = new Map();
const kdItems = kdResp && kdResp.tasks && kdResp.tasks[0] && kdResp.tasks[0].result && kdResp.tasks[0].result[0] && kdResp.tasks[0].result[0].items;
if (Array.isArray(kdItems)) {
  for (const it of kdItems) {
    if (it && it.keyword) {
      const kd = typeof it.keyword_difficulty === 'number' ? it.keyword_difficulty : null;
      kdMap.set(String(it.keyword).toLowerCase(), kd);
    }
  }
}

const keywords = (prev.keywords || []).map(kw => ({
  ...kw,
  kd: kdMap.has(kw.keyword) ? kdMap.get(kw.keyword) : kw.kd
}));

return [{ json: {
  seed_keyword: prev.seed_keyword,
  location: prev.location,
  language: prev.language,
  is_global: prev.is_global,
  keywords,
  requested_at: prev.requested_at
}}];

const input = $input.first().json;
return [{ json: {
  request: {
    seed_keyword: input.seed_keyword,
    location: input.location || 'Global',
    language: input.language
  },
  keywords: input.keywords.map(k => ({
    keyword: k.keyword,
    search_volume: k.search_volume,
    kd: k.kd,
    intent: k.intent || 'informational',
    intent_confidence: k.intent_confidence || null
  })),
  generated_at: new Date().toISOString()
}}];

const input = $input.first().json;
const body = (input && typeof input.body === 'object' && input.body !== null) ? input.body : input;

const keyword = String(body.keyword || '').trim();
if (!keyword) throw new Error('keyword is required');

const location = String(body.location || '').trim();
const language = String(body.language || 'en').trim();
let depth = Number(body.depth);
if (!Number.isFinite(depth)) depth = 10;
depth = Math.max(5, Math.min(depth, 30));
const isGlobal = !location || location.toLowerCase() === 'global';
const dr_threshold = Math.max(5, Math.min(50, Number(body.dr_threshold) || 20));

return [{ json: {
  keyword,
  location: isGlobal ? '' : location,
  language,
  depth,
  dr_threshold,
  is_global: isGlobal,
  requested_at: body.requested_at || new Date().toISOString()
}}];

const input = $input.first().json;
const task = {
  keyword: input.keyword,
  language_code: input.language,
  device: 'desktop',
  depth: input.depth
};
if (!input.is_global) {
  task.location_name = input.location;
}
return [{ json: { ...input, dfs_body: [task] } }];

const input = $('Normalize Input - SERP').first().json;
const resp = $input.first().json;

const taskResult = resp && resp.tasks && resp.tasks[0] && resp.tasks[0].result && resp.tasks[0].result[0];
if (!taskResult) {
  return [{ json: {
    results: [],
    features: {},
    request: { keyword: input.keyword, location: input.location || 'Global', language: input.language, depth: input.depth },
    error: 'No SERP result from DataForSEO',
    generated_at: new Date().toISOString()
  }}];
}

const items = taskResult.items || [];

const organic = items
  .filter(i => i.type === 'organic')
  .slice(0, input.depth)
  .map(r => ({
    position: r.rank_absolute,
    title: r.title,
    url: r.url,
    domain: r.domain || '',
    description: r.description || ''
  }));

const paaItem = items.find(i => i.type === 'people_also_ask');
const paa = paaItem && Array.isArray(paaItem.items)
  ? paaItem.items.slice(0, 8).map(q => q.title).filter(Boolean)
  : [];

const relatedItem = items.find(i => i.type === 'related_searches');
const related = relatedItem && Array.isArray(relatedItem.items)
  ? relatedItem.items.slice(0, 10)
  : [];

const featured = items.find(i => i.type === 'featured_snippet') || null;
const aiOverview = items.find(i => i.type === 'ai_overview') || null;
const knowledgeGraph = items.find(i => i.type === 'knowledge_graph') || null;

return [{ json: {
  results: organic,
  features: {
    people_also_ask: paa,
    related_searches: related,
    featured_snippet: featured ? { title: featured.title, description: featured.description, url: featured.url } : null,
    ai_overview: aiOverview ? { present: true } : null,
    knowledge_graph: knowledgeGraph ? { title: knowledgeGraph.title, description: knowledgeGraph.description } : null
  },
  request: {
    keyword: input.keyword,
    location: input.location || 'Global',
    language: input.language,
    depth: input.depth
  },
  dr_threshold: input.dr_threshold || 20,
  generated_at: new Date().toISOString()
}}];

const input = $input.first().json;
const results = input.results || [];

const HIGH_AUTHORITY = new Set([
  'youtube.com', 'wikipedia.org', 'amazon.com', 'facebook.com', 'twitter.com',
  'instagram.com', 'linkedin.com', 'pinterest.com', 'tiktok.com',
  'forbes.com', 'nytimes.com', 'wsj.com', 'bbc.com', 'cnn.com', 'reuters.com',
  'theguardian.com', 'washingtonpost.com', 'usatoday.com', 'nbcnews.com',
  'cbsnews.com', 'abcnews.go.com', 'foxnews.com', 'nypost.com',
  'healthline.com', 'webmd.com', 'mayoclinic.org', 'clevelandclinic.org',
  'nih.gov', 'cdc.gov', 'who.int', 'medlineplus.gov'
]);

const UGC_PATTERNS = /reddit\.com|quora\.com|stackoverflow\.com|stackexchange\.com|medium\.com|substack\.com|blogspot\.com|wordpress\.com|quora\.com|discord\.com|github\.com|gitlab\.com|facebook\.com\/groups|youtube\.com\/channel/i;

const domains = [];
const domainSet = new Set();
for (const r of results) {
  const d = (r.domain || '').replace(/^www\./, '').toLowerCase();
  if (!d || domainSet.has(d)) continue;
  domainSet.add(d);
  const isHighAuthority = HIGH_AUTHORITY.has(d);
  const isUgc = UGC_PATTERNS.test(d);
  domains.push({ domain: d, isHighAuthority, isUgc });
}

return [{ json: { ...input, domains: domains.filter(d => !d.isHighAuthority) } }];

const prev = $('Collect Domains').first().json;
const rankResp = $input.first().json;
const results = prev.results || [];
const domainMeta = prev.domains || [];
\nconst DR_THRESHOLD = Number(input.dr_threshold) || 20;

const UGC_PATTERNS = /reddit\.com|quora\.com|stackoverflow\.com|stackexchange\.com|medium\.com|substack\.com|blogspot\.com|wordpress\.com|quora\.com|discord\.com|github\.com|gitlab\.com|facebook\.com\/groups|youtube\.com\/channel/i;

const drMap = new Map();
const rankItems = rankResp && rankResp.tasks && rankResp.tasks[0] && rankResp.tasks[0].result && rankResp.tasks[0].result[0] && rankResp.tasks[0].result[0].items;
if (Array.isArray(rankItems)) {
  for (const item of rankItems) {
    if (item && item.target) {
      const d = String(item.target).replace(/^www\./, '').toLowerCase();
      const rank = typeof item.rank === 'number' ? item.rank : 0;
      const dr = Math.round(rank / 10);
      drMap.set(d, dr);
    }
  }
}

let greenFruits = 0;
let ugcCount = 0;
let weakSpotsCount = 0;
let weakTop3 = 0;

const enriched = results.map(r => {
  const d = (r.domain || '').replace(/^www\./, '').toLowerCase();
  const dr = drMap.has(d) ? drMap.get(d) : null;
  const isUgc = UGC_PATTERNS.test(d);
  const isHighAuthority = [
    'youtube.com', 'wikipedia.org', 'amazon.com', 'facebook.com', 'twitter.com',
    'instagram.com', 'linkedin.com', 'forbes.com', 'nytimes.com', 'bbc.com',
    'healthline.com', 'webmd.com', 'mayoclinic.org', 'nih.gov', 'cdc.gov'
  ].includes(d);

  let weakSpotType = null;
  if (!isHighAuthority) {
    if (isUgc) {
      weakSpotType = 'blue_fruit';
      ugcCount++;
      weakSpotsCount++;
    } else if (dr !== null && dr < DR_THRESHOLD) {
      weakSpotType = 'green_fruit';
      greenFruits++;
      weakSpotsCount++;
      if (r.position <= 3) weakTop3++;
    }
  }

  return { ...r, dr, weak_spot_type: weakSpotType };
});

let serpDifficulty;
if (greenFruits + ugcCount >= 3 || weakTop3 >= 2) {
  serpDifficulty = 1;
} else if (weakSpotsCount >= 1) {
  serpDifficulty = 2;
} else {
  serpDifficulty = 3;
}

return [{ json: {
  ...prev,
  results: enriched,
  weak_spot_summary: {
    green_fruits: greenFruits,
    ugc_count: ugcCount,
    weak_spots_count: weakSpotsCount,
    serp_difficulty: serpDifficulty
  }
}}];
